  // returned_order(O) :- lineitem(O,_,_,_,_,_,r,_,_,_,_,_,_).
  (function() {
    return _.flatten(map(function(e1) {
      var O = e1.t[0];
      return [['returned_order', [O], e1.v]];
    }, (lineitem_by_7[keyOf(['r'])] || [])));
  })()
