var customer_nation_by_1 = index(customer_nation, [0]);
var instances_q10_customer = [].concat(
  // q10_customer(C) :- orders(O,C,_,Date,_), Date >= 19931001, Date < 19940101, returned_order(O), customer_nation(C,_).
  (function() {
    return _.flatten(map(function(e1) {
      var O = e1.t[0];
      var C = e1.t[1];
      var Date = e1.t[3];
      if (Date >= 19931001) {
        if (Date < 19940101) {
          return _.flatten(map(function(e2) {
            return _.flatten(map(function(e3) {
              return [['q10_customer', [C], and([e1.v, e2.v, e3.v])]];
            }, (customer_nation_by_1[keyOf([C])] || [])));
          }, probe(returned_order, [O])));
        } else {
          return [];
        }
      } else {
        return [];
      }
    }, _.values(orders)));
  })()
