var q10_customer = relation({}, instances_q10_customer);

var instances_q10 = [].concat(
  // q10 :- q10_customer(_).
  (function() {
    return _.flatten(map(function(e1) {
      return [['q10', [], e1.v]];
    }, _.values(q10_customer)));
